//go:build windows

package monitor

import (
	"encoding/hex"
	"os"
	"testing"
)

// Full EDID captured from this machine's registry for the G95NC.
const g95ncEDID = ""

func TestParseEDIDModel(t *testing.T) {
	blob, err := hex.DecodeString(g95ncEDID)
	if err != nil {
		t.Fatal(err)
	}
	got := parseEDIDModel(blob)
	if got != "Odyssey G95NC" {
		t.Errorf("parseEDIDModel = %q, want %q", got, "Odyssey G95NC")
	}
	if parseEDIDModel([]byte{0, 0, 0}) != "" {
		t.Error("truncated EDID should yield empty model")
	}
}

func TestDebugEDID(t *testing.T) {
	if os.Getenv("MONCTL_DEBUG") == "" {
		t.Skip("debug only")
	}
	t.Logf("registry lookup: %q", edidModel(`MONITOR\SAM73D0\{4d36e96e-e325-11ce-bfc1-08002be10318}\0003`))
}
